<script lang="ts">import {goto} from '$app/navigation';import {auth} from '$lib/api';import {session} from '$lib/stores/session';import TopNav from '$lib/components/TopNav.svelte';let role=$state<'farmer'|'producer'>('farmer'),name=$state(''),email=$state(''),lightningAddress=$state(''),password=$state(''),error=$state(''),loading=$state(false);async function submit(){if(loading)return;const blink=lightningAddress.trim().toLowerCase();if(!name.trim()||!email.trim()||!password||!blink){error='Complete all fields.';return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(blink)){error='Enter a valid Blink Lightning Address.';return}loading=true;error='';try{const {user}=await auth.register({name:name.trim(),email:email.trim(),password,role,lightningAddress:blink});session.set(user);await goto('/dashboard')}catch(e){error=e instanceof Error?e.message:'Unable to create account.'}finally{loading=false}}</script>
<svelte:head><title>Register · RegenFeed</title></svelte:head><TopNav/><main class="stitch-auth stitch-register"><form class="stitch-card register-stitch-card" onsubmit={(e)=>{e.preventDefault();submit()}}><div class="stitch-heading"><h1>Join RegenFeed</h1><p>Create an account to begin.</p></div><div class="stitch-role"><button type="button" class:chosen={role==='farmer'} onclick={()=>role='farmer'}>I'm a Farmer</button><button type="button" class:chosen={role==='producer'} onclick={()=>role='producer'}>I'm a Producer</button></div>{#if error}<p class="error" role="alert">{error}</p>{/if}<label>{role==='farmer'?'Farm':'Business'} Name<div class="stitch-input"><input bind:value={name} autocomplete="organization" placeholder={role==='farmer'?'e.g. Lakeview Farm':'e.g. Kisumu Fresh Hotel'} required /></div></label><label>Email Address<div class="stitch-input"><input bind:value={email} type="email" autocomplete="email" placeholder="you@example.com" required /></div></label><label>Blink Lightning Address<div class="stitch-input"><input bind:value={lightningAddress} type="email" inputmode="email" placeholder="username@blink.sv" required /></div></label><label>Create Password<div class="stitch-input"><input bind:value={password} type="password" autocomplete="new-password" minlength="8" placeholder="••••••••" required /></div></label><label class="stitch-check"><input type="checkbox" required /> <span>I agree to the <a href="/">Terms & Conditions</a></span></label><button class="stitch-button" disabled={loading}>{loading?'Creating Account…':'Create Account'} <i class="fa-solid fa-arrow-right"></i></button><p class="stitch-switch">Already have an account? <a href="/auth/login">Log In</a></p></form></main>
